<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { listAgentLibrary, listTeamPresets } from '../api/agent-library.api'
import { startWorkflowRun } from '../api/workflow.api'
import type { AgentLibraryProfile, AgentTeamPreset } from '../types/agent-library'
import { useProjectSetupStore } from '../stores/projectSetup'

const route = useRoute(); const router = useRouter(); const setup = useProjectSetupStore(); const projectKey = String(route.params.projectKey); const profiles = ref<AgentLibraryProfile[]>([]); const presets = ref<AgentTeamPreset[]>([]); const source = ref<'SYSTEM_PRESET' | 'PROJECT_COPY' | 'CUSTOM'>('SYSTEM_PRESET'); const initialRequest = ref(''); const contextSnapshot = ref('{}'); const selectedPreset = ref<string | number | null>(null); const sourceProjectKey = ref(''); const error = ref(''); const starting = ref(false)
const selectedNode = computed(() => setup.configuration?.nodes.find((node) => `${node.stageKey}/${node.nodeKey}` === setup.selectedNodeKey)); const selectedAgent = computed(() => profiles.value.find((profile) => profile.code === selectedNode.value?.agentProfileCode)); const ready = computed(() => setup.configuration?.status === 'READY');
onMounted(async () => { await Promise.all([setup.load(projectKey), setup.loadReusable(projectKey), listAgentLibrary().then((items) => { profiles.value = items }), listTeamPresets().then((items) => { presets.value = items; selectedPreset.value = items.find((item) => item.isDefault)?.versionId ?? items[0]?.versionId ?? null })]) })
async function applySource() { error.value = ''; try { if (source.value === 'SYSTEM_PRESET' && selectedPreset.value != null) await setup.usePreset(projectKey, selectedPreset.value); else if (source.value === 'PROJECT_COPY' && sourceProjectKey.value) await setup.copyFrom(projectKey, sourceProjectKey.value) } catch (cause) { error.value = cause instanceof Error ? cause.message : '配置来源应用失败' } }
async function replaceAgent(versionId: string | number) { if (!selectedNode.value) return; try { await setup.replaceNode(projectKey, selectedNode.value.stageKey, selectedNode.value.nodeKey, versionId) } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Agent 替换失败' } }
async function validate() { try { await setup.validate(projectKey) } catch (cause) { error.value = cause instanceof Error ? cause.message : '配置校验失败' } }
async function confirm() { try { await setup.confirm(projectKey) } catch (cause) { error.value = cause instanceof Error ? cause.message : '配置确认失败' } }
async function start() { if (!initialRequest.value.trim() || !ready.value || starting.value) return; starting.value = true; try { const context = JSON.parse(contextSnapshot.value || '{}'); const run = await startWorkflowRun(projectKey, { initialRequest: initialRequest.value.trim(), contextSnapshotJson: context }); await router.push({ name: 'project-workspace', params: { projectId: projectKey, runId: String(run.id) } }) } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Workflow 启动失败' } finally { starting.value = false } }
</script>
<template><main class="setup"><header><div><p class="eyebrow">PROJECT AGENT SETUP</p><h1>项目 Agent 配置</h1><p class="muted">项目：{{ projectKey }} · 配置确认后启动时冻结版本。</p></div><span class="status">{{ setup.configuration?.status || 'DRAFT' }}</span></header><p v-if="error" class="error">{{ error }}</p><section class="panel source"><h2>配置来源</h2><div class="source-tabs"><button v-for="item in [['SYSTEM_PRESET','系统推荐方案'],['PROJECT_COPY','复用历史项目'],['CUSTOM','自定义']]" :key="item[0]" :class="{active:source===item[0]}" @click="source=item[0] as typeof source">{{ item[1] }}</button></div><div v-if="source==='SYSTEM_PRESET'" class="source-row"><select v-model="selectedPreset"><option v-for="preset in presets" :key="String(preset.versionId)" :value="preset.versionId">{{ preset.name }} v{{ preset.versionNo }}</option></select><button @click="applySource">应用系统方案</button></div><div v-else-if="source==='PROJECT_COPY'" class="source-row"><select v-model="sourceProjectKey"><option value="">选择历史项目</option><option v-for="item in setup.reusableProjects" :key="item.projectKey" :value="item.projectKey">{{ item.name }} · {{ item.status }}</option></select><button @click="applySource">精确复用配置</button></div><p v-else class="muted">自定义模式下，选择下方 Node 并替换已发布 Agent Version。</p></section><section class="panel"><h2>Workflow / Agent Tree</h2><div class="tree"><button v-for="node in setup.configuration?.nodes ?? []" :key="`${node.stageKey}/${node.nodeKey}`" :class="{active:setup.selectedNodeKey===`${node.stageKey}/${node.nodeKey}`}" @click="setup.selectedNodeKey=`${node.stageKey}/${node.nodeKey}`"><strong>{{ node.stageKey }}</strong><span>{{ node.nodeName || node.nodeKey }}</span><small>{{ node.agentProfileCode || '未配置' }}</small></button></div><div v-if="selectedNode" class="node-detail"><h3>{{ selectedNode.stageKey }} / {{ selectedNode.nodeKey }}</h3><label>替换 Agent<select :value="selectedNode.agentProfileVersionId" @change="replaceAgent(Number(($event.target as HTMLSelectElement).value))"><option v-for="profile in profiles" :key="profile.code" :value="profile.latestVersion?.id">{{ profile.name }} · {{ profile.latestVersion?.versionNo }} · {{ profile.sourceType }}</option></select></label><h4>System Prompt 预览</h4><pre>{{ selectedAgent?.latestVersion?.systemPrompt || '—' }}</pre><h4>Skills</h4><ul><li v-for="skill in selectedAgent?.latestVersion?.skills ?? []" :key="skill.skillKey">{{ skill.name || skill.skillKey }} · {{ skill.versionPolicy }}<span v-if="skill.required"> · Required</span></li></ul></div></section><section class="panel validation"><h2>配置校验</h2><button @click="validate">校验配置</button><div v-if="setup.validation"><p v-for="check in setup.validation.checks ?? []" :key="check.label" :class="check.passed ? 'pass' : 'fail'">{{ check.passed ? '✓' : '✕' }} {{ check.label }}</p><p v-for="issue in setup.validation.issues" :key="issue" class="fail">✕ {{ issue }}</p></div></section><section class="panel start"><h2>确认并启动研发</h2><textarea data-testid="initial-request" v-model="initialRequest" rows="4" placeholder="输入真实需求（必填）"/><textarea v-model="contextSnapshot" rows="2" placeholder="contextSnapshotJson（可选 JSON）"/><button class="primary" :disabled="setup.configuration?.status==='LOCKED'||!ready||!initialRequest.trim()" @click="start">启动 Workflow</button><button v-if="setup.configuration?.status!=='LOCKED'" class="secondary" @click="confirm">确认配置为 READY</button></section></main></template>
<style scoped>.setup{max-width:1100px;margin:auto}.setup header{display:flex;justify-content:space-between;align-items:start}.eyebrow{color:var(--accent-500);font-size:11px;letter-spacing:.14em}.muted{color:var(--text-2)}.status{padding:6px 10px;border-radius:99px;background:var(--surface-2)}.panel{padding:20px;margin:16px 0;border:1px solid var(--border-1);border-radius:16px;background:var(--surface-1)}.source-tabs{display:flex;gap:8px}.source-tabs button,.source-row button,.validation>button,.secondary{padding:9px 12px;border:1px solid var(--border-1);border-radius:8px;background:var(--surface-2)}.source-tabs .active{color:#fff;background:var(--accent-600)}.source-row{display:flex;gap:8px;margin-top:14px}.source-row select,.node-detail select{min-width:240px;padding:9px}.tree{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.tree button{display:grid;gap:4px;padding:12px;text-align:left;color:var(--text-1);border:1px solid var(--border-1);border-radius:8px;background:var(--surface-2)}.tree button.active{border-color:var(--accent-500)}.tree span,.tree small{color:var(--text-2);font-size:12px}.node-detail{margin-top:16px;padding-top:16px;border-top:1px solid var(--border-1)}.node-detail label{display:grid;gap:6px}.node-detail pre{white-space:pre-wrap;max-height:150px;overflow:auto}.validation .pass{color:#259d68}.validation .fail,.error{color:#c85757}.start textarea{display:block;width:100%;box-sizing:border-box;margin:8px 0;padding:10px;color:var(--text-1);border:1px solid var(--border-1);border-radius:8px;background:var(--surface-2)}.primary{padding:10px 15px;color:#fff;border:0;border-radius:8px;background:var(--accent-600)}@media(max-width:700px){.tree{grid-template-columns:1fr}.setup header{display:block}}
</style>
